    if max(stress, anxiety) >= 0.75:
        trigger_support_flow(
            user_id,
            options=["take_a_break", "simplify_problem", "show_free_hint", "contact_support"]
        )
        log_event(user_id, "premium_offer_suppressed", reason="acute_distress")
