    # Infer the learning need from task context—not from emotional vulnerability.
    context = get_current_learning_context(user_id)

    feature = select_feature_by_learning_need(context)
    offer = build_transparent_offer(feature, context)

    # Require the learner to dismiss or accept; never interrupt assessment flow.
    return {
        "shown": True,
        "offer": offer,
        "controls": {
            "accept": "Start",
            "dismiss": "Not now",
            "disable_future_offers": "Turn off offers"
        }
