            "name": "Advanced Hints",
            "description": "Step-by-step prompts that help you solve the problem yourself."
        }

    if context.get("needs_explanation"):
        return {
            "name": "AI Tutor Session",
            "description": "A guided session with explanations, examples, and practice."
        }

    return {
        "name": "Practice Review",
        "description": "Personalized review of topics you choose."
    }


def build_transparent_offer(feature, context):
    return {
        "headline": f"Optional support: {feature['name']}",
        "body": (
            f"{feature['description']} "
            "You can continue with the free tools instead—there’s no penalty for skipping."
        ),
        "price": get_current_price(feature["name"]),
        "billing_terms": get_billing_terms(feature["name"]),
        "free_alternatives": [
            "Show a free hint",
